import{_ as n,o as t,c as i,a3 as r}from"./chunks/framework.BlfGB29P.js";const c=JSON.parse('{"title":"Übersicht","description":"","frontmatter":{"title":"Übersicht"},"headers":[],"relativePath":"projects/uix/index.md","filePath":"projects/uix/index.md","lastUpdated":1793447386000}'),a={name:"projects/uix/index.md"};function s(o,e,l,d,u,g){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="ui-extension-fur-home-assistant" tabindex="-1">UI eXtension für Home Assistant <a class="header-anchor" href="#ui-extension-fur-home-assistant" aria-label="Permalink to &quot;UI eXtension für Home Assistant&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Stand geprüft am 31.10.2026</p><p>Stabile Basis: <strong>UIX 8.4.0</strong>, benötigt <strong>Home Assistant 2026.10.0 oder neuer</strong>. Alle <strong>65</strong> englischen Quellseiten wurden mit <code>dev</code>-Revision <strong>e6fb84d / 9.0.0-beta.6</strong> verglichen; DE/FR wurden um die Änderungen ergänzt. Vorschaufunktionen sind separat gekennzeichnet. Einzelheiten stehen im <a href="./translation-status">Prüfbericht</a>.</p></div><blockquote><p><strong>Unabhängige Übersetzung</strong> Diese Dokumentation ist eine unabhängige deutsche Übersetzung und wird von UGSo Software gepflegt. Sie ist nicht die offizielle Dokumentation des UIX-Projekts. Maßgeblich bleibt die englische Originaldokumentation unter <a href="https://uix.lf.technology/" target="_blank" rel="noreferrer">https://uix.lf.technology/</a>.</p><p>Basis: GitHub-Release <a href="https://github.com/Lint-Free-Technology/uix/releases/tag/v8.4.0" target="_blank" rel="noreferrer"><code>v8.4.0</code></a> vom 07.10.2026. Benötigt <strong>Home Assistant 2026.10.0 oder neuer</strong>. Original-Repository <a href="https://github.com/Lint-Free-Technology/uix" target="_blank" rel="noreferrer">Lint-Free-Technology/uix</a>, Release-Stand <a href="https://github.com/Lint-Free-Technology/uix/commit/71b8ccd38202257c070ae9970a7aac12a68a6389" target="_blank" rel="noreferrer"><code>71b8ccd</code></a>. Die stabile Basis wurde gegen diesen Release geprüft; zusätzlich berücksichtigt diese Fassung den separat gekennzeichneten Vorschau-Dokumentationsstand vom 31.10.2026. Einzelheiten und bekannte Grenzen stehen im <a href="./translation-status">Übersetzungsstatus</a>.</p><p>Vielen Dank an das UIX-Projekt für die durchdachte Umsetzung und die sehr gute englische Originaldokumentation, auf der diese deutsche Arbeitsfassung basiert.</p><p>Die originale UIX-Dokumentation ist von <a href="https://github.com/Lint-Free-Technology/uix" target="_blank" rel="noreferrer">Lint-Free-Technology/uix</a> und steht unter <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noreferrer">CC BY 4.0</a>. Code des UIX-Projekts bleibt separat unter MIT lizenziert.</p></blockquote><p><img src="https://raw.githubusercontent.com/Lint-Free-Technology/uix/f9eb8fa571dbce6cd771c53ca11dcf2401c8a933/docs/source/assets/images/mixed.png" alt="UIX Logo"></p><h2 id="was-ist-ui-extension" tabindex="-1">Was ist UI eXtension? <a class="header-anchor" href="#was-ist-ui-extension" aria-label="Permalink to &quot;Was ist UI eXtension?&quot;">​</a></h2><blockquote><p><strong>Für Card-mod-Nutzer</strong> Wenn du von Card-mod wechselst, lies zuerst die <a href="./faq">FAQ</a>. Dort sind die wichtigsten Unterschiede, Migrationspunkte und typischen Stolperstellen zusammengefasst.</p></blockquote><p>UI eXtension, kurz UIX, ist eine Home-Assistant-Integration für Anpassungen an der Oberfläche. Sie erweitert Karten, Zeilen, Badges, Dialoge und andere Frontend-Elemente mit CSS, Templates und zusätzlichen UI-Verhalten.</p><p>UIX besteht aus drei großen Bereichen:</p><ul><li><a href="./using/index">UIX Styling</a> für CSS-Anpassungen an Home-Assistant-Frontend-Elementen.</li><li><a href="./forge/index">UIX Forge</a> für dynamisch erzeugte Elemente, wiederverwendbare Vorlagen und erweiterte Sparks.</li><li><a href="./broker/index">UIX Broker</a> für deklarative Interaktionen: Browser-Events, Tastenkürzel und Home-Assistant-Events wählen ein Element aus, prüfen Regeln und führen Direktiven in ihrer Reihenfolge aus.</li></ul><h2 id="neu-in-uix-8-4-0" tabindex="-1">Neu in UIX 8.4.0 <a class="header-anchor" href="#neu-in-uix-8-4-0" aria-label="Permalink to &quot;Neu in UIX 8.4.0&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Vorschau: UIX 9.0.0-beta.6</p><p><a href="./using/custom-sidebar-panels">Eigene Seitenleisten-Verknüpfungen</a> sind ab <strong>9.0.0-beta.6</strong> verfügbar. Der <a href="./forge/forge#visual-editor-cards-and-badges">visuelle Forge-Editor</a> ist ab <strong>9.0.0-beta.2</strong> verfügbar und bietet <strong>Convert to visual editor</strong> für bestehende direkte Karten-/Badge-Forges. Die stabile Basis bleibt <strong>8.4.0</strong>.</p></div><ul><li><a href="./forge/sparks/form">Form Spark</a> und <a href="./extras/uix-actions#popover">Popover-Aktion</a> für Formulare und eingeblendete Inhalte.</li><li><a href="./extras/style-frame-panels">Frame-Panels stylen</a> mit interner Frame-Laufzeit; diese experimentelle Option bleibt standardmäßig deaktiviert.</li><li><a href="./using/themes">Theme-Schriften mit <code>uix-fonts</code></a> und <a href="./using/images">Entitätsbilder in Kartenübersichten</a>, einschließlich der Anpassung an Home Assistant 2026.10.</li><li><a href="./broker/directives#direktiven-regeln">Broker-Direktiven-Regeln</a> können Ergebnisse früherer JavaScript- oder Template-Direktiven verwenden.</li></ul><p>Die zuvor beschriebenen 8.4-Beta-Ergänzungen gehören damit zur stabilen Version. Historische Versionshinweise kennzeichnen weiterhin die Einführung einzelner Funktionen.</p><h2 id="schnell-loslegen" tabindex="-1">Schnell loslegen <a class="header-anchor" href="#schnell-loslegen" aria-label="Permalink to &quot;Schnell loslegen&quot;">​</a></h2><p>Der beste Einstieg ist der <a href="./quick-start">Schnellstart</a>. Dort findest du Installation, Einrichtung als Home-Assistant-Dienst und je ein erstes Beispiel für UIX Styling und UIX Forge.</p><h2 id="wichtige-bereiche" tabindex="-1">Wichtige Bereiche <a class="header-anchor" href="#wichtige-bereiche" aria-label="Permalink to &quot;Wichtige Bereiche&quot;">​</a></h2><ul><li><a href="./using/index">UIX Styling verwenden</a></li><li><a href="./forge/index">UIX Forge verwenden</a></li><li><a href="./broker/index">UIX Broker verwenden</a></li><li><a href="./concepts/index">Konzepte verstehen</a></li><li><a href="./debugging/index">Debugging</a></li><li><a href="./faq">FAQ</a></li></ul><blockquote><p><strong>Stand dieser deutschen Doku</strong> Am 31.10.2026 gegen die stabile Basis <code>8.4.0</code> und den Dokumentationsstand <code>dev e6fb84d / 9.0.0-beta.6</code> geprüft. Bei Unklarheiten gilt immer die englische Originaldokumentation.</p></blockquote>',18)])])}const f=n(a,[["render",s]]);export{c as __pageData,f as default};
